@classmethod
def extract(cls, tb: Optional[TracebackType] = None) -> List[Frame]:
    """Extract a list of frames from a traceback."""
    if tb is None:
        tb = sys.exc_info()[2]

    frames: List[Frame] = []
    for frame, lineno in traceback.walk_tb(tb):
        frames.append(
            Frame(
                filename=frame.f_code.co_filename,
                lineno=lineno,
                name=frame.f_code.co_name,
                line=traceback.StackSummary.from_frame(frame).extract(0).line,
                locals=pretty.pprint(frame.f_locals),
            )
        )
    return frames
